/**
 * @notice Interface for ReferralSystem contract
 */
interface IReferralSystem {
    function registerReferral(address referee, address referrer) external;
    function recordPurchase(address buyer, uint256 usdAmount, uint256 tokensAmount) external;
}

/**
 * @title HypeAI Private Sale Contract with Referral Integration
 * @notice Founding Members Private Sale with VIP benefits + Referral System
 * @dev Enhanced version of PrivateSale.sol with integrated referral tracking
 *
 * NEW FEATURES:
 * - Referral code system
 * - Automatic referral tracking on purchase
 * - Integration with ReferralSystem.sol contract
 * - Backward compatible with original PrivateSale
 */
contract HypeAIPrivateSaleWithReferral is Ownable, ReentrancyGuard, Pausable {

    // ============ STATE VARIABLES ============

    // Token being sold
    IERC20 public hypeaiToken;

    // USDT token for payments (BSC: 0x55d398326f99059fF775485246999027B3197955)
    IERC20 public usdtToken;

    // Referral system contract
    IReferralSystem public referralSystem;

    // Sale parameters (10B tokenomics: prices ÷10, amounts ×10)
    uint256 public constant TOKEN_PRICE = 8 * 10**13; // $0.00008 in wei (assuming BNB = $600)
    uint256 public constant MIN_PURCHASE_USD = 400; // $400 minimum
    uint256 public constant MAX_PURCHASE_USD = 8000; // $8,000 maximum
    uint256 public constant HARD_CAP_USD = 80000; // $80,000 hard cap
    uint256 public constant BONUS_PERCENTAGE = 10; // 10% bonus tokens

    uint256 public constant TOKENS_FOR_SALE = 1_100_000_000 * 10**18; // 1.1B tokens (includes 10% bonus buffer)
    uint256 public constant MAX_FOUNDING_MEMBERS = 500;

    // Sale state
    uint256 public totalTokensSold;
    uint256 public totalUSDRaised;
    uint256 public foundingMembersCount;
    uint256 public saleStartTime;
    uint256 public saleEndTime;
    bool public saleFinalized;

    // Whitelist for private sale
    mapping(address => bool) public whitelist;
    mapping(address => uint256) public contributions; // In USD
    mapping(address => uint256) public tokensPurchased;
    mapping(address => bool) public isFoundingMember;

    // Events
    event WhitelistUpdated(address indexed user, bool status);
    event TokensPurchased(
        address indexed buyer,
        uint256 usdAmount,
        uint256 tokensAmount,
        uint256 bonusTokens,
        bool paymentMethod, // true = BNB, false = USDT
        address indexed referrer // NEW: Referrer tracking
    );
    event SaleFinalized(uint256 totalRaised, uint256 totalTokensSold);
    event TokensWithdrawn(address indexed recipient, uint256 amount);
    event FundsWithdrawn(address indexed recipient, uint256 bnbAmount, uint256 usdtAmount);
    event ReferralSystemUpdated(address indexed oldSystem, address indexed newSystem);

    constructor(
        address _hypeaiToken,
        address _usdtToken,
        address _referralSystem,
        uint256 _saleStartTime,
        uint256 _saleDuration
    ) Ownable(msg.sender) {
        require(_hypeaiToken != address(0), "Invalid token address");
        require(_usdtToken != address(0), "Invalid USDT address");
        require(_referralSystem != address(0), "Invalid referral system");
        require(_saleStartTime > 0, "Invalid start time");

        hypeaiToken = IERC20(_hypeaiToken);
        usdtToken = IERC20(_usdtToken);
        referralSystem = IReferralSystem(_referralSystem);
        saleStartTime = _saleStartTime;
        saleEndTime = _saleStartTime + _saleDuration;
    }

    /**
     * @notice Add addresses to whitelist
     * @param _addresses Array of addresses to whitelist
     */
    function addToWhitelist(address[] calldata _addresses) external onlyOwner {
        for (uint256 i = 0; i < _addresses.length; i++) {
            whitelist[_addresses[i]] = true;
            emit WhitelistUpdated(_addresses[i], true);
        }
    }

    /**
     * @notice Remove addresses from whitelist
     * @param _addresses Array of addresses to remove
     */
    function removeFromWhitelist(address[] calldata _addresses) external onlyOwner {
        for (uint256 i = 0; i < _addresses.length; i++) {
            whitelist[_addresses[i]] = false;
            emit WhitelistUpdated(_addresses[i], false);
        }
    }

    /**
     * @notice Purchase tokens with BNB (NO referral)
     * @dev Backward compatible with original contract
     */
    function purchaseWithBNB() external payable nonReentrant whenNotPaused {
        _purchaseWithBNB(address(0));
    }

    /**
     * @notice Purchase tokens with BNB (WITH referral)
     * @param _referrer Address of referrer (optional, use address(0) for none)
     */
    function purchaseWithBNB(address _referrer) external payable nonReentrant whenNotPaused {
        _purchaseWithBNB(_referrer);
    }

    /**
     * @notice Purchase tokens with USDT (NO referral)
     * @param _usdtAmount Amount of USDT to spend
     * @dev Backward compatible with original contract
     */
    function purchaseWithUSDT(uint256 _usdtAmount) external nonReentrant whenNotPaused {
        _purchaseWithUSDT(_usdtAmount, address(0));
    }

    /**
     * @notice Purchase tokens with USDT (WITH referral)
     * @param _usdtAmount Amount of USDT to spend
     * @param _referrer Address of referrer (optional, use address(0) for none)
     */
    function purchaseWithUSDT(uint256 _usdtAmount, address _referrer) external nonReentrant whenNotPaused {
        _purchaseWithUSDT(_usdtAmount, _referrer);
    }

    /**
     * @notice Internal BNB purchase handler
     */
    function _purchaseWithBNB(address _referrer) internal {
        require(block.timestamp >= saleStartTime, "Sale not started");
        require(block.timestamp <= saleEndTime, "Sale ended");
        require(whitelist[msg.sender], "Not whitelisted");
        require(!saleFinalized, "Sale finalized");
        require(foundingMembersCount < MAX_FOUNDING_MEMBERS, "Max members reached");

        // Calculate USD value (1 BNB = $600)
        uint256 usdValue = (msg.value * 600) / 10**18;

        require(usdValue >= MIN_PURCHASE_USD, "Below minimum purchase");
        require(
            contributions[msg.sender] + usdValue <= MAX_PURCHASE_USD,
            "Exceeds maximum purchase"
        );
        require(
            totalUSDRaised + usdValue <= HARD_CAP_USD,
            "Exceeds hard cap"
        );

        _processPurchase(msg.sender, usdValue, _referrer, true);
    }

    /**
     * @notice Internal USDT purchase handler
     */
    function _purchaseWithUSDT(uint256 _usdtAmount, address _referrer) internal {
        require(block.timestamp >= saleStartTime, "Sale not started");
        require(block.timestamp <= saleEndTime, "Sale ended");
        require(whitelist[msg.sender], "Not whitelisted");
        require(!saleFinalized, "Sale finalized");
        require(foundingMembersCount < MAX_FOUNDING_MEMBERS, "Max members reached");

        // USDT has 18 decimals on BSC
        uint256 usdValue = _usdtAmount / 10**18;

        require(usdValue >= MIN_PURCHASE_USD, "Below minimum purchase");
        require(
            contributions[msg.sender] + usdValue <= MAX_PURCHASE_USD,
            "Exceeds maximum purchase"
        );
        require(
            totalUSDRaised + usdValue <= HARD_CAP_USD,
            "Exceeds hard cap"
        );

        // Transfer USDT from buyer
        require(
            usdtToken.transferFrom(msg.sender, address(this), _usdtAmount),
            "USDT transfer failed"
        );

        _processPurchase(msg.sender, usdValue, _referrer, false);
    }

    /**
     * @notice Internal function to process purchase with referral tracking
     * @param _buyer Address of buyer
     * @param _usdValue USD value of purchase
     * @param _referrer Address of referrer (can be address(0))
     * @param _isBNB True if payment is BNB, false if USDT
     */
    function _processPurchase(
        address _buyer,
        uint256 _usdValue,
        address _referrer,
        bool _isBNB
    ) internal {
        // Calculate tokens (1 HYPEAI = $0.00008) - 10B tokenomics
        // tokens = usdValue / 0.00008 = usdValue * 12500
        uint256 baseTokens = _usdValue * 12500 * 10**18;

        // Calculate bonus (10%)
        uint256 bonusTokens = (baseTokens * BONUS_PERCENTAGE) / 100;
        uint256 totalTokens = baseTokens + bonusTokens;

        require(
            totalTokensSold + totalTokens <= TOKENS_FOR_SALE,
            "Not enough tokens left"
        );

        // Update state
        contributions[_buyer] += _usdValue;
        tokensPurchased[_buyer] += totalTokens;
        totalUSDRaised += _usdValue;
        totalTokensSold += totalTokens;

        // Mark as Founding Member if first purchase
        if (!isFoundingMember[_buyer]) {
            isFoundingMember[_buyer] = true;
            foundingMembersCount++;
        }

        // ============ REFERRAL INTEGRATION ============
        // Register referral if provided and valid
        if (_referrer != address(0) && _referrer != _buyer) {
            try referralSystem.registerReferral(_buyer, _referrer) {
                // Registration successful or already registered
            } catch {
                // Silently fail if already registered or invalid
            }
        }

        // Record purchase in referral system
        try referralSystem.recordPurchase(_buyer, _usdValue, totalTokens) {
            // Successfully recorded
        } catch {
            // Silently fail if referral system unavailable
        }
        // ============ END REFERRAL INTEGRATION ============

        // Transfer tokens immediately
        require(
            hypeaiToken.transfer(_buyer, totalTokens),
            "Token transfer failed"
        );

        emit TokensPurchased(
            _buyer,
            _usdValue,
            baseTokens,
            bonusTokens,
            _isBNB,
            _referrer
        );
    }

    /**
     * @notice Check if address is eligible for purchase
     * @param _address Address to check
     * @return eligible True if can purchase
     * @return remainingAllocation Remaining USD allocation
     * @return tokensWouldReceive Tokens they would receive for their remaining allocation
     */
    function checkEligibility(address _address)
        external
        view
        returns (
            bool eligible,
            uint256 remainingAllocation,
            uint256 tokensWouldReceive
        )
    {
        if (!whitelist[_address]) {
            return (false, 0, 0);
        }

        if (block.timestamp < saleStartTime || block.timestamp > saleEndTime) {
            return (false, 0, 0);
        }

        if (saleFinalized) {
            return (false, 0, 0);
        }

        if (foundingMembersCount >= MAX_FOUNDING_MEMBERS && !isFoundingMember[_address]) {
            return (false, 0, 0);
        }

        remainingAllocation = MAX_PURCHASE_USD - contributions[_address];

        if (remainingAllocation == 0) {
            return (false, 0, 0);
        }

        // Calculate tokens with bonus (10B tokenomics: ×10)
        uint256 baseTokens = remainingAllocation * 12500 * 10**18;
        tokensWouldReceive = baseTokens + (baseTokens * BONUS_PERCENTAGE / 100);

        eligible = true;
    }

    /**
     * @notice Get sale statistics
     */
    function getSaleStats()
        external
        view
        returns (
            uint256 _totalUSDRaised,
            uint256 _totalTokensSold,
            uint256 _foundingMembersCount,
            uint256 _remainingTokens,
            uint256 _remainingUSDCap,
            uint256 _timeRemaining,
            bool _isActive
        )
    {
        _totalUSDRaised = totalUSDRaised;
        _totalTokensSold = totalTokensSold;
        _foundingMembersCount = foundingMembersCount;
        _remainingTokens = TOKENS_FOR_SALE - totalTokensSold;
        _remainingUSDCap = HARD_CAP_USD - totalUSDRaised;

        if (block.timestamp < saleEndTime) {
            _timeRemaining = saleEndTime - block.timestamp;
        } else {
            _timeRemaining = 0;
        }

        _isActive = (
            block.timestamp >= saleStartTime &&
            block.timestamp <= saleEndTime &&
            !saleFinalized &&
            totalUSDRaised < HARD_CAP_USD
        );
    }

    /**
     * @notice Update referral system contract
     * @param _newReferralSystem New referral system address
     */
    function setReferralSystem(address _newReferralSystem) external onlyOwner {
        require(_newReferralSystem != address(0), "Invalid address");
        address oldSystem = address(referralSystem);
        referralSystem = IReferralSystem(_newReferralSystem);
        emit ReferralSystemUpdated(oldSystem, _newReferralSystem);
    }

    /**
     * @notice Finalize sale (can only be called after sale ends)
     */
    function finalizeSale() external onlyOwner {
        require(block.timestamp > saleEndTime || totalUSDRaised >= HARD_CAP_USD, "Sale still active");
        require(!saleFinalized, "Already finalized");

        saleFinalized = true;

        emit SaleFinalized(totalUSDRaised, totalTokensSold);
    }

    /**
     * @notice Withdraw unsold tokens (only after finalization)
     */
    function withdrawUnsoldTokens() external onlyOwner {
        require(saleFinalized, "Sale not finalized");

        uint256 unsoldTokens = TOKENS_FOR_SALE - totalTokensSold;

        if (unsoldTokens > 0) {
            require(
                hypeaiToken.transfer(owner(), unsoldTokens),
                "Token transfer failed"
            );

            emit TokensWithdrawn(owner(), unsoldTokens);
        }
    }

    /**
     * @notice Withdraw raised funds (only after finalization)
     */
    function withdrawFunds() external onlyOwner {
        require(saleFinalized, "Sale not finalized");

        uint256 bnbBalance = address(this).balance;
        uint256 usdtBalance = usdtToken.balanceOf(address(this));

        if (bnbBalance > 0) {
            (bool success, ) = owner().call{value: bnbBalance}("");
            require(success, "BNB transfer failed");
        }

        if (usdtBalance > 0) {
            require(
                usdtToken.transfer(owner(), usdtBalance),
                "USDT transfer failed"
            );
        }

        emit FundsWithdrawn(owner(), bnbBalance, usdtBalance);
    }

    /**
     * @notice Emergency pause
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Update sale end time (only before sale ends)
     */
    function extendSale(uint256 _newEndTime) external onlyOwner {
        require(_newEndTime > saleEndTime, "Must extend, not shorten");
        require(block.timestamp < saleEndTime, "Sale already ended");

        saleEndTime = _newEndTime;
    }

    /**
     * @notice Accept BNB payments
     */
    receive() external payable {
        revert("Use purchaseWithBNB() function");
    }
}

src/contracts/ReferralSystem.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title HypeAI Referral System
 * @notice Automated referral tracking and reward distribution for HYPEAI token sales
 * @dev Integrates with HypeAIPrivateSale contract to track purchases and distribute rewards
 *
 * Features:
 * - Multi-tier referral rewards (5% direct, 2% second-tier)
 * - Flexible reward payment (HYPE tokens OR USDT)
 * - Anti-fraud protection (no self-referral, max caps)
 * - Automatic reward calculation and distribution
 * - Comprehensive statistics tracking
 * - Emergency pause functionality
 */
contract HypeAIReferralSystem is Ownable, ReentrancyGuard, Pausable {

    // ============ STATE VARIABLES ============

    /// @notice HYPEAI token contract
    IERC20 public immutable hypeToken;

    /// @notice USDT token contract for alternative rewards
    IERC20 public immutable usdtToken;

    /// @notice Private sale contract (authorized to call recordPurchase)
    address public privateSaleContract;

    /// @notice Referral reward percentage (in basis points: 100 = 1%)
    uint256 public constant DIRECT_REFERRAL_REWARD = 500; // 5%

    /// @notice Second-tier referral reward percentage
    uint256 public constant SECOND_TIER_REWARD = 200; // 2%

    /// @notice Maximum reward cap per referrer in USD
    uint256 public constant MAX_REWARD_CAP_USD = 10000; // $10,000 max earnings

    /// @notice Minimum purchase amount to count as referral in USD (10B tokenomics: ×10)
    uint256 public constant MIN_REFERRAL_PURCHASE = 400; // $400

    /// @notice Basis points denominator
    uint256 private constant BASIS_POINTS = 10000;

    // ============ STRUCTS ============

    /**
     * @notice Comprehensive referral data structure
     * @param referrer Address of the user who referred this account
     * @param secondTierReferrer Address of the referrer's referrer (for 2-tier rewards)
     * @param totalReferred Total number of users referred
     * @param totalVolume Total USD volume generated by referrals
     * @param pendingRewardsUSD Pending rewards in USD value
     * @param totalEarnedUSD Total USD value earned (all-time)
     * @param totalClaimedUSD Total USD value claimed
     * @param rewardInTokens True = claim in HYPE tokens, False = claim in USDT
     * @param isActive Whether this referral account is active
     */
    struct ReferralData {
        address referrer;
        address secondTierReferrer;
        uint256 totalReferred;
        uint256 totalVolume;
        uint256 pendingRewardsUSD;
        uint256 totalEarnedUSD;
        uint256 totalClaimedUSD;
        bool rewardInTokens;
        bool isActive;
    }

    // ============ MAPPINGS ============

    /// @notice Mapping of user address to their referral data
    mapping(address => ReferralData) public referrals;

    /// @notice Mapping to track referred users by referrer
    mapping(address => address[]) public referredUsers;

    /// @notice Blacklist for fraud prevention
    mapping(address => bool) public blacklisted;

    /// @notice Track if user has registered a referral
    mapping(address => bool) public hasReferrer;

    // ============ EVENTS ============

    event ReferralRegistered(
        address indexed referee,
        address indexed referrer,
        address indexed secondTierReferrer
    );

    event PurchaseRecorded(
        address indexed buyer,
        uint256 usdAmount,
        uint256 tokensAmount,
        address indexed directReferrer,
        uint256 directReward,
        address indexed secondTierReferrer,
        uint256 secondTierReward
    );

    event RewardsClaimed(
        address indexed user,
        uint256 usdValue,
        uint256 tokenAmount,
        bool inTokens
    );

    event RewardPreferenceChanged(
        address indexed user,
        bool inTokens
    );

    event PrivateSaleContractUpdated(
        address indexed oldContract,
        address indexed newContract
    );

    event UserBlacklisted(address indexed user, bool status);

    event EmergencyWithdrawal(
        address indexed token,
        address indexed recipient,
        uint256 amount
    );

    // ============ MODIFIERS ============

    /**
     * @notice Only allow calls from the authorized private sale contract
     */
    modifier onlyPrivateSale() {
        require(msg.sender == privateSaleContract, "Only private sale contract");
        _;
    }

    /**
     * @notice Prevent blacklisted users from interacting
     */
    modifier notBlacklisted(address _user) {
        require(!blacklisted[_user], "User is blacklisted");
        _;
    }

    // ============ CONSTRUCTOR ============

    /**
     * @notice Initialize the referral system
     * @param _hypeToken HYPEAI token address
     * @param _usdtToken USDT token address
     * @param _privateSaleContract Initial private sale contract address
     */
    constructor(
        address _hypeToken,
        address _usdtToken,
        address _privateSaleContract
    ) Ownable(msg.sender) {
        require(_hypeToken != address(0), "Invalid HYPE token");
        require(_usdtToken != address(0), "Invalid USDT token");
        require(_privateSaleContract != address(0), "Invalid sale contract");

        hypeToken = IERC20(_hypeToken);
        usdtToken = IERC20(_usdtToken);
        privateSaleContract = _privateSaleContract;
    }

    // ============ EXTERNAL FUNCTIONS ============

    /**
     * @notice Register a referral relationship
     * @param _referee Address being referred
     * @param _referrer Address of the referrer
     * @dev Can only be called once per referee, prevents self-referral and circular references
     */
    function registerReferral(
        address _referee,
        address _referrer
    )
        external
        whenNotPaused
        notBlacklisted(_referee)
        notBlacklisted(_referrer)
    {
        require(_referee != address(0), "Invalid referee");
        require(_referrer != address(0), "Invalid referrer");
        require(_referee != _referrer, "Cannot refer yourself");
        require(!hasReferrer[_referee], "Already has referrer");
        require(_referee != owner(), "Owner cannot be referred");

        // Prevent circular referrals
        require(referrals[_referrer].referrer != _referee, "Circular referral");

        // Get second-tier referrer (referrer's referrer)
        address secondTier = referrals[_referrer].referrer;

        // Initialize referral data
        referrals[_referee] = ReferralData({
            referrer: _referrer,
            secondTierReferrer: secondTier,
            totalReferred: 0,
            totalVolume: 0,
            pendingRewardsUSD: 0,
            totalEarnedUSD: 0,
            totalClaimedUSD: 0,
            rewardInTokens: true, // Default to HYPE tokens
            isActive: true
        });

        hasReferrer[_referee] = true;
        referredUsers[_referrer].push(_referee);

        emit ReferralRegistered(_referee, _referrer, secondTier);
    }

    /**
     * @notice Record a purchase and calculate referral rewards
     * @param _buyer Address of the buyer
     * @param _usdAmount USD amount spent
     * @param _tokensAmount HYPE tokens purchased
     * @dev Only callable by authorized private sale contract
     */
    function recordPurchase(
        address _buyer,
        uint256 _usdAmount,
        uint256 _tokensAmount
    )
        external
        onlyPrivateSale
        whenNotPaused
        notBlacklisted(_buyer)
    {
        require(_usdAmount >= MIN_REFERRAL_PURCHASE, "Purchase too small");

        address directReferrer = referrals[_buyer].referrer;

        // If buyer has no referrer, no rewards to distribute
        if (directReferrer == address(0)) {
            emit PurchaseRecorded(_buyer, _usdAmount, _tokensAmount, address(0), 0, address(0), 0);
            return;
        }

        uint256 directReward = 0;
        uint256 secondTierReward = 0;

        // Calculate and distribute direct referral reward (5%)
        if (!blacklisted[directReferrer] && referrals[directReferrer].isActive) {
            directReward = (_usdAmount * DIRECT_REFERRAL_REWARD) / BASIS_POINTS;

            // Check max cap
            if (referrals[directReferrer].totalEarnedUSD + directReward <= MAX_REWARD_CAP_USD) {
                referrals[directReferrer].pendingRewardsUSD += directReward;
                referrals[directReferrer].totalEarnedUSD += directReward;
                referrals[directReferrer].totalReferred += 1;
                referrals[directReferrer].totalVolume += _usdAmount;
            } else {
                directReward = 0; // Cap reached, no reward
            }
        }

        // Calculate and distribute second-tier reward (2%)
        address secondTierReferrer = referrals[_buyer].secondTierReferrer;
        if (
            secondTierReferrer != address(0) &&
            !blacklisted[secondTierReferrer] &&
            referrals[secondTierReferrer].isActive
        ) {
            secondTierReward = (_usdAmount * SECOND_TIER_REWARD) / BASIS_POINTS;

            // Check max cap
            if (referrals[secondTierReferrer].totalEarnedUSD + secondTierReward <= MAX_REWARD_CAP_USD) {
                referrals[secondTierReferrer].pendingRewardsUSD += secondTierReward;
                referrals[secondTierReferrer].totalEarnedUSD += secondTierReward;
                // Don't increment totalReferred for second-tier (they didn't directly refer)
            } else {
                secondTierReward = 0; // Cap reached
            }
        }

        emit PurchaseRecorded(
            _buyer,
            _usdAmount,
            _tokensAmount,
            directReferrer,
            directReward,
            secondTierReferrer,
            secondTierReward
        );
    }

    /**
     * @notice Claim pending referral rewards
     * @param _inTokens True to receive HYPE tokens, false for USDT
     * @dev Calculates token amount based on current token price ($0.00008 - 10B tokenomics)
     */
    function claimRewards(bool _inTokens)
        external
        nonReentrant
        whenNotPaused
        notBlacklisted(msg.sender)
    {
        ReferralData storage userData = referrals[msg.sender];

        require(userData.pendingRewardsUSD > 0, "No pending rewards");
        require(userData.isActive, "Account not active");

        uint256 rewardUSD = userData.pendingRewardsUSD;
        userData.pendingRewardsUSD = 0;
        userData.totalClaimedUSD += rewardUSD;

        if (_inTokens) {
            // Calculate HYPE tokens (1 HYPE = $0.00008, so tokens = usdValue / 0.00008 = usdValue * 12500)
            uint256 tokenAmount = rewardUSD * 12500 * 10**18;

            require(
                hypeToken.balanceOf(address(this)) >= tokenAmount,
                "Insufficient HYPE tokens in contract"
            );

            require(
                hypeToken.transfer(msg.sender, tokenAmount),
                "HYPE transfer failed"
            );

            emit RewardsClaimed(msg.sender, rewardUSD, tokenAmount, true);
        } else {
            // Pay in USDT (1:1 with USD)
            uint256 usdtAmount = rewardUSD * 10**18; // USDT has 18 decimals on BSC

            require(
                usdtToken.balanceOf(address(this)) >= usdtAmount,
                "Insufficient USDT in contract"
            );

            require(
                usdtToken.transfer(msg.sender, usdtAmount),
                "USDT transfer failed"
            );

            emit RewardsClaimed(msg.sender, rewardUSD, usdtAmount, false);
        }
    }

    /**
     * @notice Change reward payment preference
     * @param _inTokens True for HYPE tokens, false for USDT
     */
    function setRewardPreference(bool _inTokens) external {
        referrals[msg.sender].rewardInTokens = _inTokens;
        emit RewardPreferenceChanged(msg.sender, _inTokens);
    }

    // ============ VIEW FUNCTIONS ============

    /**
     * @notice Get comprehensive referral statistics for a user
     * @param _user Address to query
     * @return referrer Direct referrer address
     * @return secondTierReferrer Second-tier referrer address
     * @return totalReferred Number of direct referrals
     * @return totalVolume Total USD volume from referrals
     * @return pendingRewardsUSD Pending rewards in USD
     * @return totalEarnedUSD Total earned (all-time)
     * @return totalClaimedUSD Total claimed amount
     * @return rewardInTokens Payment preference
     * @return isActive Account status
     */
    function getReferralStats(address _user)
        external
        view
        returns (
            address referrer,
            address secondTierReferrer,
            uint256 totalReferred,
            uint256 totalVolume,
            uint256 pendingRewardsUSD,
            uint256 totalEarnedUSD,
            uint256 totalClaimedUSD,
            bool rewardInTokens,
            bool isActive
        )
    {
        ReferralData memory data = referrals[_user];
        return (
            data.referrer,
            data.secondTierReferrer,
            data.totalReferred,
            data.totalVolume,
            data.pendingRewardsUSD,
            data.totalEarnedUSD,
            data.totalClaimedUSD,
            data.rewardInTokens,
            data.isActive
        );
    }

    /**
     * @notice Get pending rewards for a user in both USD and tokens
     * @param _user Address to query
     * @return usdValue Pending rewards in USD
     * @return hypeTokens Equivalent HYPE tokens at current price (10B tokenomics)
     * @return usdtTokens Equivalent USDT tokens
     */
    function getPendingRewards(address _user)
        external
        view
        returns (
            uint256 usdValue,
            uint256 hypeTokens,
            uint256 usdtTokens
        )
    {
        usdValue = referrals[_user].pendingRewardsUSD;
        hypeTokens = usdValue * 12500 * 10**18; // 1 HYPE = $0.00008 (10B tokenomics)
        usdtTokens = usdValue * 10**18; // 1 USDT = $1
    }

    /**
     * @notice Get list of users referred by an address
     * @param _referrer Referrer address
     * @return Array of referred user addresses
     */
    function getReferredUsers(address _referrer)
        external
        view
        returns (address[] memory)
    {
        return referredUsers[_referrer];
    }

    /**
     * @notice Get leaderboard data (top referrers by volume)
     * @param _addresses Array of addresses to check
     * @return volumes Array of total volumes
     * @return referralCounts Array of referral counts
     */
    function getLeaderboard(address[] calldata _addresses)
        external
        view
        returns (
            uint256[] memory volumes,
            uint256[] memory referralCounts
        )
    {
        volumes = new uint256[](_addresses.length);
        referralCounts = new uint256[](_addresses.length);

        for (uint256 i = 0; i < _addresses.length; i++) {
            volumes[i] = referrals[_addresses[i]].totalVolume;
            referralCounts[i] = referrals[_addresses[i]].totalReferred;
        }
    }

    // ============ ADMIN FUNCTIONS ============

    /**
     * @notice Update the private sale contract address
     * @param _newContract New contract address
     */
    function setPrivateSaleContract(address _newContract) external onlyOwner {
        require(_newContract != address(0), "Invalid contract address");
        address oldContract = privateSaleContract;
        privateSaleContract = _newContract;
        emit PrivateSaleContractUpdated(oldContract, _newContract);
    }

    /**
     * @notice Blacklist or unblacklist a user
     * @param _user User address
     * @param _status True to blacklist, false to unblacklist
     */
    function setBlacklisted(address _user, bool _status) external onlyOwner {
        blacklisted[_user] = _status;
        if (_status) {
            referrals[_user].isActive = false;
        }
        emit UserBlacklisted(_user, _status);
    }

    /**
     * @notice Deactivate a referral account (fraud prevention)
     * @param _user User to deactivate
     */
    function deactivateAccount(address _user) external onlyOwner {
        referrals[_user].isActive = false;
    }

    /**
     * @notice Fund the contract with HYPE tokens for rewards
     * @param _amount Amount of HYPE tokens to fund
     */
    function fundHypeRewards(uint256 _amount) external onlyOwner {
        require(
            hypeToken.transferFrom(msg.sender, address(this), _amount),
            "Transfer failed"
        );
    }

    /**
     * @notice Fund the contract with USDT for rewards
     * @param _amount Amount of USDT to fund
     */
    function fundUsdtRewards(uint256 _amount) external onlyOwner {
        require(
            usdtToken.transferFrom(msg.sender, address(this), _amount),
            "Transfer failed"
        );
    }

    /**
     * @notice Emergency withdrawal of tokens
     * @param _token Token address (HYPE or USDT)
     * @param _amount Amount to withdraw
     */
    function emergencyWithdraw(address _token, uint256 _amount) external onlyOwner {
        require(_token == address(hypeToken) || _token == address(usdtToken), "Invalid token");

        IERC20 token = IERC20(_token);
        require(
            token.transfer(owner(), _amount),
            "Transfer failed"
        );

        emit EmergencyWithdrawal(_token, owner(), _amount);
    }

    /**
     * @notice Pause the contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause the contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }
}

